mapper.select:
select b.id, b.title, b.content, b.cover, b.create_time,
       b.update_time, b.user_id, b.category_id,
       b.status, u.username
from  blog b
    left join user u on b.user_id = u.id


        and b.status = #{status}


        and (b.status = 0 or b.status = 6)


        and u.username = #{username}


        and b.title = #{title}


order by create_time
